import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const artifactPath = path.join(
  root,
  "artifacts",
  "contracts",
  "XNSMultichainResolver.sol",
  "XNSMultichainResolver.json",
);
const artifact = JSON.parse(fs.readFileSync(artifactPath, "utf8"));

if (
  !Array.isArray(artifact.abi) ||
  typeof artifact.bytecode !== "string" ||
  !artifact.bytecode.startsWith("0x") ||
  artifact.bytecode.length <= 2
) {
  throw new Error("Invalid Hardhat artifact for XNSMultichainResolver");
}

const target = path.join(
  root,
  "frontend",
  "generated",
  "apothemMultichainResolverDeployment.ts",
);
fs.mkdirSync(path.dirname(target), { recursive: true });
fs.writeFileSync(
  target,
  [
    "// Generated from Hardhat artifacts during the build.",
    "// Do not edit this file manually.",
    "export const apothemMultichainResolverDeploymentArtifact = " +
      JSON.stringify({ abi: artifact.abi, bytecode: artifact.bytecode }) +
      " as const;",
    "",
  ].join("\n"),
);
console.log("Generated", path.relative(root, target));
